    #[test]
    fn positional_callable_record_constructor_rejects_a_forged_result_type() {
        let source = r#"type Scale = pure(n: Int) -> Int
type RenamedScale = pure(value: Int) -> Int
type Holder = {callback: Scale}
type RenamedHolder = {callback: RenamedScale}
pure double(n: Int) -> Int { n * 2 }
pure identity(value: Int) -> Int { value }
test test_typed_callable_record_field_is_called_like_a_method {
  assert Holder(double).callback(4) == 8
  assert RenamedHolder(identity).callback(4) == 4
}
"#;
        let program = fixture("typed-callable-positional-record.xsh", source);
        let callback_name = program_name(&program, "callback");
        let callback_has_parameter_name = |ty: &Type, wanted: &str| {
            let Type::Record(fields) = ty else {
                return false;
            };
            let Some(Type::Callable(callable)) = fields.get(&callback_name) else {
                return false;
            };
            callable
                .sig
                .params
                .first()
                .is_some_and(|param| param.name.as_str().as_str() == wanted)
        };
        let try_require_fact = |wanted_parameter_name: &str| {
            program
                .store
                .checked_expr_types
                .iter()
                .enumerate()
                .find_map(|(fact_index, fact)| {
                    let instruction = fact.instruction as usize;
                    if program.store.tags.get(instruction) != Some(&FullTag::ExprTry) {
                        return None;
                    }
                    let try_payload = program
                        .store
                        .payload(program.store.data[instruction].range())
                        .ok()?;
                    let require = *try_payload.first()? as usize;
                    if program.store.tags.get(require) != Some(&FullTag::ExprRequire) {
                        return None;
                    }
                    let fact_type = program.store.semantic.to_type(fact.type_id).ok()?;
                    callback_has_parameter_name(&fact_type, wanted_parameter_name)
                        .then_some((instruction, require, fact_index, fact.type_id))
                })
        };
        let (try_instruction, require, fact_index, _) = try_require_fact("n")
            .expect("positional constructor propagation has the original callback type");
        let (_, _, _, forged_type) = try_require_fact("value")
            .expect("fixture has a second callable record with an incompatible parameter label");
        let forged_callable = program
            .store
            .semantic
            .field_type(forged_type, callback_name)
            .expect("forged record field decodes")
            .expect("forged record has a callback field");
        let (typed_call, field_callee) = program
            .store
            .tags
            .iter()
            .enumerate()
            .find_map(|(instruction, tag)| {
                if *tag != FullTag::ExprTypedCall {
                    return None;
                }
                let call_payload = program
                    .store
                    .payload(program.store.data[instruction].range())
                    .ok()?;
                let callee = *call_payload.first()? as usize;
                if program.store.tags.get(callee) != Some(&FullTag::ExprField) {
                    return None;
                }
                let field_payload = program
                    .store
                    .payload(program.store.data[callee].range())
                    .ok()?;
                (*field_payload.first()? as usize == try_instruction)
                    .then_some((instruction, callee))
            })
            .expect("direct constructor field call has a typed-call instruction");
        let field_fact_index = program
            .store
            .checked_expr_types
            .binary_search_by_key(&(field_callee as u32), |fact| fact.instruction)
            .expect("direct constructor field has a callable fact");

        let mut forged = program.clone();
        let require_payload = forged.store.data[require].range();
        forged.store.extra[require_payload.start as usize + 1] = forged_type.raw();
        forged.store.checked_expr_types[fact_index].type_id = forged_type;
        forged.store.checked_expr_types[field_fact_index].type_id = forged_callable;
        let call_payload = forged.store.data[typed_call].range();
        forged.store.extra[call_payload.start as usize + 2] = forged_callable.raw();
        let error = FullVerifier::verify(&forged).unwrap_err();
        assert!(
            error.message.contains("checked expression child type disagrees with its producer"),
            "{}",
            error.message
        );
    }

    #[test]
    fn optional_producer_derivation_keeps_callable_contracts_strict() {
        let program = fixture("optional-producer-contracts.xsh", r#"use hash
pure digest(data: Bytes) -> Digest { hash.md5(data) }
guard let value = Ok(1) else { exit 3 }
print $value
"#);
        FullVerifier::verify(&program).unwrap();
        let block = (0..program.store.driver_steps.len()).find_map(|step| {
            program.store.driver_instruction_range(step).unwrap()
                .find(|instruction| program.store.tags[*instruction] == FullTag::ExprValueBlock)
        }).unwrap();
        let calls = function_instruction_indices(&program, "digest", FullTag::ExprModuleCall);
        assert_eq!(calls.len(), 1);
        let callable = Type::Callable(Arc::new(crate::sema::types::TypedCallable {
            pure: true,
            sig: crate::sema::types::CallableType {
                params: Vec::new(),
                return_ty: Box::new(Type::Int),
                effects: None,
            },
        }));
        for (instruction, message) in [
            (block, "checked value block has no value tail"),
            (calls[0], "checked API operation has ambiguous return types"),
        ] {
            let mut forged = program.clone();
            let type_id = SemanticPoolBuilder::default()
                .intern_type(&mut forged.store.semantic, &callable).unwrap();
            let fact = FullCheckedExprType {
                instruction: instruction as u32,
                type_id,
                purpose: FullCheckedExprPurpose::CheckedContract {
                    function_ref: None,
                    with_error_source: false,
                },
            };
            let insert = forged.store.checked_expr_types
                .partition_point(|existing| existing.instruction < fact.instruction);
            forged.store.checked_expr_types.insert(insert, fact);
            let error = FullVerifier::verify(&forged).unwrap_err();
            assert!(error.message.contains(message), "{}", error.message);
        }
    }

    #[test]
    fn typed_callable_literal_containers_reject_forged_element_types() {
        let source = r#"type Scale = pure(n: Int) -> Int
type Holder = {callback: Pure}
pure double(n: Int) -> Int { n * 2 }
pure label_length(text: Str) -> Int { text.byte_len() }
pure typed_map_value() -> Int {
  let callbacks: Map[Str, Scale] = {["double"]: double}
  callbacks.len()
}
proc callback_from_literal_map() [error] -> Result[Int] {
  let callbacks: Map[Str, Scale] = {["double"]: double}
  with selected = callbacks.get("double") {
    return Ok(selected(4))
  } else { |failure| return Err(failure) }
}
pure map_value() -> Int {
  let callbacks: Map[Str, Pure] = {["label"]: label_length}
  callbacks.len()
}
pure noncallable_map_value() -> Int {
  let callbacks: Map[Str, Int] = {["label"]: 1}
  callbacks.len()
}
pure spread_map_value(callbacks: Map[Str, Scale]) -> Int {
  let merged: Map[Str, Scale] = {...callbacks}
  merged.len()
}
pure empty_map_value() -> Int {
  let callbacks: Map[Str, Scale] = {}
  callbacks.len()
}
pure list_value() -> Int {
  let callbacks: List[Pure] = [label_length]
  callbacks.len()
}
pure record_value() -> Pure {
  let holder: Holder = {callback: label_length}
  holder.callback
}
test test_typed_callable_literal_containers {
  assert typed_map_value() == 1
  assert callback_from_literal_map()? == 8
  assert map_value() == 1
  assert list_value() == 1
}
"#;
        let program = fixture("typed-callable-literal-containers.xsh", source);
        FullVerifier::verify(&program).unwrap();

        let scale = Type::Callable(Arc::new(crate::sema::types::TypedCallable {
            pure: true,
            sig: crate::sema::types::CallableType {
                params: vec![crate::sema::types::CallableParamType {
                    name: program_name(&program, "n"),
                    ty: Type::Int,
                    defaulted: false,
                    rest: false,
                }],
                return_ty: Box::new(Type::Int),
                effects: None,
            },
        }));
        let mut record_fields = BTreeMap::new();
        record_fields.insert(program_name(&program, "callback"), scale.clone());
        let container_types = [
            (
                "map_value",
                FullTag::ExprMapLiteral,
                Type::Map(Box::new(Type::Str), Box::new(scale.clone())),
            ),
            (
                "list_value",
                FullTag::ExprList,
                Type::List(Box::new(scale.clone())),
            ),
            ("record_value", FullTag::ExprRecord, Type::Record(record_fields.into())),
        ];
        for (function, tag, forged_type) in container_types {
            let instructions = function_instruction_indices(&program, function, tag);
            assert_eq!(instructions.len(), 1, "{function} has one {tag:?} producer");
            let instruction = instructions[0];
            assert!(
                program
                    .store
                    .checked_expr_types
                    .binary_search_by_key(&(instruction as u32), |fact| fact.instruction)
                    .is_err()
            );
            let mut forged = program.clone();
            let mut semantic = SemanticPoolBuilder::default();
            let type_id = semantic
                .intern_type(&mut forged.store.semantic, &forged_type)
                .unwrap();
            let fact = FullCheckedExprType {
                instruction: instruction as u32,
                type_id,
                purpose: FullCheckedExprPurpose::CheckedContract { function_ref: None, with_error_source: false },
            };
            let insert = forged
                .store
                .checked_expr_types
                .partition_point(|existing| existing.instruction < fact.instruction);
            forged.store.checked_expr_types.insert(insert, fact);

            let error = FullVerifier::verify(&forged).unwrap_err();
            assert!(
                error.message.contains("checked function reference tail disagrees with its target signature"),
                "{tag:?}: {}",
                error.message
            );
        }

        let noncallable_map = function_instruction_indices(
            &program,
            "noncallable_map_value",
            FullTag::ExprMapLiteral,
        );
        assert_eq!(noncallable_map.len(), 1);
        let mut forged = program.clone();
        let mut semantic = SemanticPoolBuilder::default();
        let type_id = semantic
            .intern_type(
                &mut forged.store.semantic,
                &Type::Map(Box::new(Type::Str), Box::new(scale.clone())),
            )
            .unwrap();
        let fact = FullCheckedExprType {
            instruction: noncallable_map[0] as u32,
            type_id,
            purpose: FullCheckedExprPurpose::CheckedContract { function_ref: None, with_error_source: false },
        };
        let insert = forged
            .store
            .checked_expr_types
            .partition_point(|existing| existing.instruction < fact.instruction);
        forged.store.checked_expr_types.insert(insert, fact);
        let error = FullVerifier::verify(&forged).unwrap_err();
        assert!(
            error.message.contains("checked callable expression child has no structural producer proof"),
            "{}",
            error.message
        );

        let spread_map = function_instruction_indices(
            &program,
            "spread_map_value",
            FullTag::ExprMapLiteral,
        );
        assert_eq!(spread_map.len(), 1);
        let decoder = return_analysis_decoder(&program, "spread_map_value");
        let mut entries = match decoder.expression_view(spread_map[0]).unwrap() {
            schema::ExprView::MapLiteral(entries) => entries,
            _ => unreachable!("spread map instruction has a map literal view"),
        };
        let (key, spread_operand, _) = entries.next().unwrap().unwrap();
        assert!(key.is_none());
        assert!(entries.next().is_none());
        let spread_operand = spread_operand.raw() as usize;
        assert_eq!(program.store.tags[spread_operand], FullTag::ExprParam);

        let mut forged_spread_type = program.clone();
        let mut semantic = SemanticPoolBuilder::default();
        let incompatible_map_type = semantic
            .intern_type(
                &mut forged_spread_type.store.semantic,
                &Type::Map(Box::new(Type::Int), Box::new(scale.clone())),
            )
            .unwrap();
        let fact_index = forged_spread_type
            .store
            .checked_expr_types
            .binary_search_by_key(&(spread_map[0] as u32), |fact| fact.instruction)
            .expect("spread map has a checked type fact");
        forged_spread_type.store.checked_expr_types[fact_index].type_id = incompatible_map_type;
        let error = FullVerifier::verify(&forged_spread_type).unwrap_err();
        assert!(
            error
                .message
                .contains("checked callable expression slot disagrees with its expected type"),
            "{}",
            error.message
        );

        let empty_map = function_instruction_indices(
            &program,
            "empty_map_value",
            FullTag::ExprEmptyMap,
        );
        assert_eq!(empty_map.len(), 1);
        let mut forged = program.clone();
        let mut semantic = SemanticPoolBuilder::default();
        let type_id = semantic
            .intern_type(
                &mut forged.store.semantic,
                &Type::Map(Box::new(Type::Str), Box::new(scale)),
            )
            .unwrap();
        let fact = FullCheckedExprType {
            instruction: empty_map[0] as u32,
            type_id,
            purpose: FullCheckedExprPurpose::CheckedContract { function_ref: None, with_error_source: false },
        };
        let insert = forged
            .store
            .checked_expr_types
            .partition_point(|existing| existing.instruction < fact.instruction);
        forged.store.checked_expr_types.insert(insert, fact);
        FullVerifier::verify(&forged).unwrap();
    }

    #[test]
    fn typed_callable_record_return_facts_reject_field_and_receiver_corruption() {
        let source = r#"type Scale = pure(n: Int) -> Int
type Holder = {callback: Scale, count: Int}
type OtherHolder = {callback: Int}

pure double(n: Int) -> Int {
  n * 2
}

pure get_holder() -> Holder {
  Holder(callback: double, count: 0)
}

pure get_other_holder() -> OtherHolder {
  OtherHolder(callback: 0)
}

pure get_spread_holder() -> Holder {
  Holder(...{callback: double, count: 0})
}

pure apply_result(n: Int) -> Int {
  get_holder().callback(n)
}

pure apply_spread_result(n: Int) -> Int {
  get_spread_holder().callback(n)
}
"#;
        let program = fixture("typed-callable-record-result.xsh", source);
        FullVerifier::verify(&program).unwrap();
        fn payload(program: &FullProgram, instruction: usize) -> &[u32] {
            program
                .store
                .payload(program.store.data[instruction].range())
                .unwrap()
        }
        let field_callee = program
            .store
            .tags
            .iter()
            .enumerate()
            .filter(|(_, tag)| **tag == FullTag::ExprTypedCall)
            .find_map(|(instruction, _)| {
                let callee = *payload(&program, instruction).first()? as usize;
                (program.store.tags.get(callee) == Some(&FullTag::ExprField))
                    .then_some(callee)
            })
            .expect("record-return field typed call exists");
        assert_eq!(
            program.store.string(payload(&program, field_callee)[1]).unwrap(),
            "callback"
        );
        let reject = |program: &FullProgram| {
            let error = FullVerifier::verify(program).unwrap_err();
            assert!(
                error
                    .message
                    .contains("typed call signature differs from its callee field's callable type"),
                "{}",
                error.message
            );
        };

        let mut wrong_field = program.clone();
        let count_name = u32::try_from(wrong_field.store.strings.len() + 1).unwrap();
        let start = u32::try_from(wrong_field.store.string_bytes.len()).unwrap();
        wrong_field.store.string_bytes.extend_from_slice(b"count");
        wrong_field.store.strings.push(IrRange::new(start, 5));
        wrong_field.store.extra[wrong_field.store.data[field_callee].range().start as usize + 1] =
            count_name;
        reject(&wrong_field);

        let receiver = payload(&program, field_callee)[0] as usize;
        assert!(matches!(
            program.store.tags[receiver],
            FullTag::ExprCall | FullTag::ExprDirectPureCall
        ));
        let alternate = program
            .store
            .functions
            .iter()
            .position(|function| program.store.string(function.name).unwrap() == "get_other_holder")
            .expect("alternate record producer exists");
        let mut wrong_receiver = program.clone();
        wrong_receiver.store.extra
            [wrong_receiver.store.data[receiver].range().start as usize] =
            IrFunctionId::new(alternate).unwrap().raw();
        reject(&wrong_receiver);
    }

